package com.shazwan.idash3;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.view.accessibility.*;import java.util.*;
/** Exercises the real vendored Compose navigation inside the Drive host. No catalogue fixtures. */
public class BitChordChecks extends Instrumentation {
 LauncherActivity a;int n;android.content.SharedPreferences p;Map<String,?> saved;
 void check(boolean b,String why){if(!b)throw new AssertionError(why);n++;}
 void ui(Runnable r){Throwable[] err={null};runOnMainSync(()->{try{r.run();}catch(Throwable t){err[0]=t;}});if(err[0]!=null)throw new AssertionError(err[0]);}
 boolean matches(CharSequence value,String label){if(value==null)return false;String text=value.toString().replace('\u00a0',' ').trim();return text.equalsIgnoreCase(label)||text.startsWith(label+"\n")||text.startsWith(label+", ");}
 AccessibilityNodeInfo node(AccessibilityNodeInfo root,String label){if(root==null)return null;if(matches(root.getText(),label)||matches(root.getContentDescription(),label)){if(!"Next".equals(label)||root.getText()!=null)return root;}for(int i=0;i<root.getChildCount();i++){AccessibilityNodeInfo found=node(root.getChild(i),label);if(found!=null)return found;}return null;}
 AccessibilityNodeInfo find(String label){AccessibilityNodeInfo hit=node(getUiAutomation().getRootInActiveWindow(),label);if(hit!=null)return hit;for(AccessibilityWindowInfo window:getUiAutomation().getWindows()){AccessibilityNodeInfo root=window.getRoot();if(root!=null&&"com.shazwan.idash3".contentEquals(root.getPackageName()==null?"":root.getPackageName())){hit=node(root,label);if(hit!=null)return hit;}}return null;}
 AccessibilityNodeInfo waitNode(String label)throws Exception{for(int i=0;i<160;i++){AccessibilityNodeInfo x=find(label);if(x!=null)return x;SystemClock.sleep(250);}throw new AssertionError("Compose semantics missing: "+label);}
 void tap(String label)throws Exception{AccessibilityNodeInfo x=waitNode(label);while(x!=null&&!x.isClickable())x=x.getParent();check(x!=null&&x.performAction(AccessibilityNodeInfo.ACTION_CLICK),"tap native "+label);}
 AccessibilityNodeInfo editable(AccessibilityNodeInfo root){if(root==null)return null;if(root.isEditable())return root;for(int i=0;i<root.getChildCount();i++){AccessibilityNodeInfo hit=editable(root.getChild(i));if(hit!=null)return hit;}return null;}
 void welcome()throws Exception{for(int i=0;i<160;i++){AccessibilityNodeInfo root=getUiAutomation().getRootInActiveWindow();if(node(root,"What should we call you?")!=null){AccessibilityNodeInfo field=editable(root);check(field!=null,"native welcome name field");Bundle args=new Bundle();args.putCharSequence(AccessibilityNodeInfo.ACTION_ARGUMENT_SET_TEXT_CHARSEQUENCE,"Native QA");check(field.performAction(AccessibilityNodeInfo.ACTION_SET_TEXT,args),"enter labelled test nickname");SystemClock.sleep(400);tap("Next");java.util.concurrent.CountDownLatch frames=new java.util.concurrent.CountDownLatch(1);ui(()->a.driveDashboard.bitChord.postOnAnimation(()->a.driveDashboard.bitChord.postOnAnimation(frames::countDown)));check(frames.await(40,java.util.concurrent.TimeUnit.SECONDS),"native connect page draws");SystemClock.sleep(1200);ui(a::hideKeyboard);int[] xy=new int[2];int[] size=new int[2];ui(()->{a.driveDashboard.bitChord.getLocationOnScreen(xy);size[0]=a.driveDashboard.bitChord.getWidth();size[1]=a.driveDashboard.bitChord.getHeight();});long now=SystemClock.uptimeMillis();float x=xy[0]+size[0]/2f,y=xy[1]+size[1]-a.dp(44);sendPointerSync(android.view.MotionEvent.obtain(now,now,android.view.MotionEvent.ACTION_DOWN,x,y,0));sendPointerSync(android.view.MotionEvent.obtain(now,now+80,android.view.MotionEvent.ACTION_UP,x,y,0));check(true,"tap visible native Skip sign in button within panel");SystemClock.sleep(1000);return;}if(node(root,"Search")!=null&&node(root,"Library")!=null)return;SystemClock.sleep(250);}throw new AssertionError("native root did not appear");}
 public void onCreate(Bundle b){super.onCreate(b);start();}
 public void onStart(){Bundle out=new Bundle();int code=Activity.RESULT_CANCELED;try{
 android.accessibilityservice.AccessibilityServiceInfo service=getUiAutomation().getServiceInfo();service.flags|=android.accessibilityservice.AccessibilityServiceInfo.FLAG_RETRIEVE_INTERACTIVE_WINDOWS|android.accessibilityservice.AccessibilityServiceInfo.FLAG_REPORT_VIEW_IDS;getUiAutomation().setServiceInfo(service); // Establish the system accessibility connection before the first heavy Compose frame.
 p=getTargetContext().getSharedPreferences("idash",0);saved=new HashMap<>(p.getAll());p.edit().putBoolean("motion",false).putBoolean("dashboard_location",false).putInt("dashboard_panel",0).apply();ActivityMonitor mon=addMonitor(LauncherActivity.class.getName(),null,false);getTargetContext().startActivity(new Intent(getTargetContext(),LauncherActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));a=(LauncherActivity)mon.waitForActivityWithTimeout(45000);removeMonitor(mon);check(a!=null,"host started");java.util.concurrent.CountDownLatch idle=new java.util.concurrent.CountDownLatch(1);a.worker.execute(()->a.main.post(idle::countDown));check(idle.await(45,java.util.concurrent.TimeUnit.SECONDS),"launcher apps loaded");
 ui(()->{a.page="drive";a.render();a.driveDashboard.setMode(4);});
 welcome();waitNode("Search");waitNode("Library");check(true,"actual upstream navigation rendered");
 ui(()->{DriveDashboard d=a.driveDashboard;BitChordPanel panel=d.bitChord;check(panel!=null&&d.map==null&&d.web==null&&d.fm==null,"native source replaces map in same host");check(panel.content.getClass().getName().equals("androidx.compose.ui.platform.ComposeView"),"actual Compose root mounted");check(panel.getWidth()>350&&panel.getHeight()>300,"usable music viewport");int[] music=new int[2],prayer=new int[2];panel.getLocationOnScreen(music);d.journey.getLocationOnScreen(prayer);check(prayer[0]+d.journey.getWidth()<=music[0],"JAKIM remains left of music without overlap");d.modeButtons[4].performClick();check(panel==d.bitChord,"repeat selection retains composition");});
 tap("Search");SystemClock.sleep(1200);waitNode("Library");tap("Library");SystemClock.sleep(1200);waitNode("Search");
 android.graphics.Bitmap image=getUiAutomation().takeScreenshot();if(image!=null){try(java.io.OutputStream f=new java.io.FileOutputStream(new java.io.File(a.getFilesDir(),"bitchord-full-ui-1024x600.png"))){image.compress(android.graphics.Bitmap.CompressFormat.PNG,100,f);}image.recycle();}
 ui(()->{DriveDashboard d=a.driveDashboard;BitChordPanel panel=d.bitChord;d.setMode(0);if(d.map!=null)d.map.setUseDataConnection(false);check(panel.closed&&panel.getChildCount()==0,"source exit disposes composition");d.setMode(4);check(d.bitChord!=panel,"native UI reopens after disposal");});waitNode("Search");check(a.hasWindowFocus(),"iDash keeps focused host activity");
 out.putString("stream","PASS: "+n+" full upstream native UI assertions\n");code=Activity.RESULT_OK;
 }catch(Throwable t){out.putString("stream","FAIL after "+n+": "+t+"\n");}finally{if(a!=null)ui(a::finish);if(p!=null&&saved!=null)AppearanceChecks.restore(p,saved);}finish(code,out);}
}
